import csv
import io
from pathlib import Path


def visible_rows(rows, tenant):
    return [row for row in rows if row["tenant"] == tenant]


def safe_destination(root, name):
    root = Path(root).resolve()
    destination = (root / name).resolve()
    if not destination.is_relative_to(root):
        raise ValueError("Export destination escapes its root")
    return destination


def render_csv(rows):
    stream = io.StringIO(newline="")
    csv.writer(stream, lineterminator="\n").writerows(rows)
    return stream.getvalue()


def send_with_retry(send):
    try:
        return send()
    except TimeoutError:
        return send()


def export_for_tenant(records, tenant):
    if not tenant:
        raise ValueError("Tenant identity is required")
    return render_csv([row["cells"] for row in visible_rows(records, tenant)])

