def tenant_jobs(jobs, tenant):
    return [job for job in jobs if job["tenant"] == tenant]

def can_start(job):
    return job["state"] == "queued"

def can_retry(attempts, maximum):
    return attempts < maximum

def retry_delay(attempt):
    return 2 ** (attempt - 1)

def has_expired(deadline, now):
    return now >= deadline

def public_job(job):
    return {key: value for key, value in job.items() if key != "access_token"}

def remaining_capacity(capacity, running):
    return max(0, capacity - running)

def idempotency_key(job):
    return (job["tenant"], job["id"])

